on:
  workflow_call:
    inputs:
      python-version:
        description: Python version passed to actions/setup-python.
        required: false
        type: string
        # Concrete rather than "3.x": a floating interpreter means the same
        # commit can resolve differently over time, and .tool-versions already
        # pins 3.14 for local work. Consumers override via this input.
        default: "3.14"
      working-directory:
        description: Directory the install and test commands run in.
        required: false
        type: string
        default: "."
      install-command:
        description: |
          Shell command that installs the project together with its test
          dependencies (must include pytest and pytest-cov).
        required: false
        type: string
        default: "pip install -e .[test]"
      coverage-source:
        description: |
          Module or package measured for coverage, passed to pytest as
          --cov=&lt;source&gt;.
        required: false
        type: string
        default: "."
      pytest-args:
        description: Extra arguments appended to the pytest invocation.
        required: false
        type: string
        default: ""
      fail-under:
        description: |
          Minimum total coverage percentage. The job fails below it.
          0 disables the gate.
        required: false
        type: number
        default: 0

jobs:
  coverage:
    name: Python Coverage
    runs-on: ubuntu-latest
    permissions:
      contents: read
    defaults:
      run:
        working-directory: ${{ inputs.working-directory }}
    steps:
      - name: Checkout sources
        uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6.1.0
        with:
          persist-credentials: false

      - uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6.3.0
        with:
          python-version: ${{ inputs.python-version }}

      - name: Install dependencies
        run: ${{ inputs.install-command }}

      - name: Run pytest with coverage
        run: |
          pytest \
            --cov=${{ inputs.coverage-source }} \
            --cov-report=term-missing \
            --cov-report=xml \
            ${{ inputs.pytest-args }}

      - name: Render coverage into the job summary
        if: ${{ !cancelled() }}
        run: |
          # Encode, then wrap, for the step summary (#506): a control character
          # becomes a question mark and an ASCII punctuation character its
          # numeric HTML entity (`@` also gets an empty comment after it, so no
          # e-mail autolink forms), inside &lt;code&gt; (md_code) or &lt;pre&gt; (md_pre,
          # line ends kept). Caller and repository text then renders as
          # text and links nothing.
          md_enc() { local LC_ALL=C; local s="${1//[[:cntrl:]]/?}" c n x; s="${s//$'\xc2'[$'\x80'-$'\x9f']/?}"; s="${s//$'\xe2\x80'[$'\xa8\xa9']/?}"; for n in {33..47} {58..64} {91..96} {123..126}; do printf -v x '%x' "$n"; printf -v c '%b' "\\x$x"; s=${s//"$c"/$'\x01'$n$'\x02'}; done; s=${s//$'\x01'64$'\x02'/$'\x01'64$'\x02\x03'}; s=${s//$'\x01'/'&amp;#'}; s=${s//$'\x02'/';'}; s=${s//$'\x03'/'&lt;!-- --&gt;'}; printf '%s' "$s"; }
          md_code() { printf '&lt;code&gt;%s&lt;/code&gt;' "$(md_enc "$1")"; }
          md_pre() { local line; printf '&lt;pre&gt;'; while IFS= read -r line; do md_enc "${line%$'\r'}"; printf '\n'; done &lt;&lt;&lt; "$1"; printf '&lt;/pre&gt;\n'; }
          # Masks $1 for a log line (#492): control characters become '?' and
          # '##[' becomes '#?[', so the value can neither end the line nor open
          # the runner's older '##[command]' syntax in the middle of one.
          shown() { local v="${1//[[:cntrl:]]/?}"; printf '%s' "${v//\#\#\[/#?[}"; }
          # The report quotes the consumer's file names: captured as plain
          # text and written as one &lt;pre&gt; block, not appended as Markdown.
          # A non-zero exit -- the consumer's own fail_under, say -- must not
          # lose it: the report reaches the summary and the log first, then
          # the step exits with coverage's own status, as before.
          status=0
          report=$(coverage report --format=text) || status=$?
          {
            echo "## Test coverage"
            echo
            md_pre "$report"
          } &gt;&gt; "$GITHUB_STEP_SUMMARY"
          while IFS= read -r line; do
            echo "coverage | $(shown "$line")"
          done &lt;&lt;&lt; "$report"
          exit "$status"

      - name: Enforce coverage threshold
        if: ${{ inputs.fail-under &gt; 0 }}
        run: coverage report --fail-under=${{ inputs.fail-under }}
